class NcfParameterEditorPage(NavigatablePage):
    """
    As a class will be called by Configuration,
    all operations on NCF Parameter Editor will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['Configuration', 'NCF Configuration', 'NCF Parameter Editor']

    def __init__(self, driver, download_checker):
        super(NcfParameterEditorPage, self).__init__(driver)
        self._view_panel = NcfParameterEditorPageViewPanel(driver, download_checker)
        self._navigation_panel = NcfParameterEditorPageNavigationPanel(driver)

    def create_ncf_plan(self, plan_name, timeout=60):
        self._view_panel.create_ncf_plan(plan_name, timeout)

    def set_ncf_parameter_value(self, dist_name, filter_param, new_value=None, node_index=None,
                                parameter_status="All parameters", abbr=None, ncf_configuration='Current', timeout=60):
        self._view_panel.set_ncf_parameter_value(dist_name, filter_param, new_value, node_index, parameter_status,
                                                 abbr, ncf_configuration, timeout)

    def get_ncf_parameter_value(self, dist_name, filter_param, node_index=None, abbr=None,
                                ncf_configuration='Current', timeout=60):
        return self._view_panel.get_ncf_parameter_value(dist_name, filter_param, node_index, abbr,
                                                        ncf_configuration, timeout)

    def load_ncf_file_and_check_load_status(self, file_path, timeout=60):
        return self._view_panel.load_ncf_file_and_check_load_status(file_path, timeout)

    def save_ncf_configuration(self):
        return self._view_panel.save_ncf_configuration()

    def remove_ncf_object(self, object_name, timeout=60):
        self._navigation_panel.remove_ncf_object(object_name, timeout)

    def add_ncf_object(self, object_name, object_class, id=None, load_default_values=False, timeout=60):
        self._navigation_panel.add_ncf_object(object_name, object_class, id, load_default_values, timeout)

    def delete_ncf_parameter(self, dist_name, filter_param, node_index=None, abbr=None, timeout=60):
        self._view_panel.delete_ncf_parameter(dist_name, filter_param, node_index, abbr, timeout)

    def validate_ncf_plan(self, timeout=60):
        self._view_panel.validate_ncf_plan(timeout)

    def activate_ncf_plan(self, timeout=10):
        return self._view_panel.activate_ncf_plan(timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class NcfParameterEditorPageNavigationPanel(NavigationPanel):
    _OBJECT_NAME_XPATH = '(//span[@title="{}" or @aria-label="{}"])'
    _REMOVE_OBJECT_BUTTON_XPATH = _OBJECT_NAME_XPATH + '//following-sibling::div//*[@a-icon="trash"]/button'
    _ADD_OBJECT_BUTTON_XPATH = _OBJECT_NAME_XPATH + '//following-sibling::div//*[@a-icon="plus"]/button'

    def __init__(self, driver):
        super(NcfParameterEditorPageNavigationPanel, self).__init__(driver)
        self.common_actions = {
            '_input_and_choose_object': ConfigurationCommonAction(driver)._input_and_choose_object,
        }
        self.__dict__.update(self.common_actions)

    def remove_ncf_object(self, object_name, timeout=60):
        object_name = self._input_and_choose_object(object_name, timeout)
        self.click_enabled_element((By.XPATH, self._REMOVE_OBJECT_BUTTON_XPATH.format(object_name, object_name)),
                                   timeout)

        remove_object_modal = RemoveNcfObjectModal(self.driver)
        remove_object_modal.wait_until_remove_object_modal_appear(timeout)
        remove_object_modal.submit(timeout)

    def add_ncf_object(self, object_name, object_class, id, load_default_values, timeout):
        object_name = self._input_and_choose_object(object_name)
        self.click_enabled_element((By.XPATH, self._ADD_OBJECT_BUTTON_XPATH.format(object_name, object_name)), timeout)

        add_object_modal = AddNcfObjectModal(self.driver)
        add_object_modal.wait_until_add_object_modal_appear(timeout)
        add_object_modal.add_object(object_class, id, load_default_values, timeout)
        add_object_modal.submit(timeout)


class NcfParameterEditorPageViewPanel(ViewPanel):
    _CREATE_NCF_PLAN_BUTTON_XPATH = '//*[contains(@a-text, "Create NCF")]//button'
    _LOAD_NCF_FILE_BUTTON_SCRIPT = 'ncf-load-action-button input'
    _LOAD_NCF_FILE_BUTTON_XPATH = '//ncf-load-action-button//input'
    _SAVE_NCF_CONFIGURATION_BUTTON_XPATH = '//*[contains(@a-text, "Save NCF Configuration")]//button'
    _PARAM_NAME_INPUT_XPATH = ('//*[contains(@class, "pe-table-header-container")]'
                               '//th[@class="pe-full-name-cell"]//input')
    _VALIDATE_NCF_BUTTON_XPATH = '//*[contains(@a-text, "Validate NCF")]//button'
    _ACTIVATE_NCF_BUTTON_XPATH = '//*[contains(@a-text, "Activate NCF")]//button'

    def __init__(self, driver, download_checker):
        super(NcfParameterEditorPageViewPanel, self).__init__(driver, download_checker)
        self._parameter_editor_page_view_panel = ParameterEditorPageViewPanel(driver)
        self.common_actions = {
            'set_ncf_parameter_value': self._parameter_editor_page_view_panel.set_parameter_value,
            'get_ncf_parameter_value': self._parameter_editor_page_view_panel.get_parameter_value,
            '_input_object_name_and_filter_param':
                self._parameter_editor_page_view_panel._input_object_name_and_filter_param,
            '_input_abbreviation': self._parameter_editor_page_view_panel._input_abbreviation,
            '_click_delete_parameter_button': self._parameter_editor_page_view_panel._click_delete_parameter_button,
        }
        self.__dict__.update(self.common_actions)

    def create_ncf_plan(self, plan_name, timeout):
        self.click_enabled_element((By.XPATH, self._CREATE_NCF_PLAN_BUTTON_XPATH), timeout)
        create_plan_modal = CreateNcfPlanModal(self.driver)
        create_plan_modal.wait_for_create_new_ncf_configuration_modal_appear(timeout)
        create_plan_modal.create_new_ncf_configuration(plan_name, timeout)

    def load_ncf_file_and_check_load_status(self, file_path, timeout):
        self.load_file_from_hidden_button(self._LOAD_NCF_FILE_BUTTON_SCRIPT,
                                          self._LOAD_NCF_FILE_BUTTON_XPATH, file_path, timeout)
        load_ncf_file_modal = LoadNcfFileModal(self.driver)
        load_ncf_file_modal.wait_until_load_file_modal_appear(timeout)
        load_status = load_ncf_file_modal.check_status_after_loading_ncf_file(timeout)
        load_ncf_file_modal.confirm()
        return load_status

    def save_ncf_configuration(self):
        self.click_enabled_element_after_visible((By.XPATH, self._SAVE_NCF_CONFIGURATION_BUTTON_XPATH))
        save_ncf_configuration_modal = SaveNcfConfigurationModal(self.driver, self.download_checker)
        save_ncf_configuration_modal.wait_until_save_ncf_configuration_modal_appear()
        return save_ncf_configuration_modal.save()

    def delete_ncf_parameter(self, dist_name, filter_param, node_index, abbr, timeout):
        self._input_object_name_and_filter_param(dist_name, filter_param, timeout)
        self._input_abbreviation(abbr, timeout)

        filter_param = filter_param.lower()
        self._click_delete_parameter_button(filter_param, node_index, timeout)

    def validate_ncf_plan(self, timeout):
        self.click_enabled_element((By.XPATH, self._VALIDATE_NCF_BUTTON_XPATH), timeout)

    def activate_ncf_plan(self, timeout):
        self.click_enabled_element((By.XPATH, self._ACTIVATE_NCF_BUTTON_XPATH), timeout)
        activate_ncf_plan_modal = ActivateNcfPlanModal(self.driver)
        activate_ncf_plan_modal.wait_until_actiavte_plan_modal_appear(timeout)
        result = activate_ncf_plan_modal.execute(timeout)
        activate_ncf_plan_modal.close()
        return result


