class NcfRelationErrorsPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Configuration', 'NCF Configuration', 'Relation Errors']

    def __init__(self, driver):
        super(NcfRelationErrorsPage, self).__init__(driver)
        self._view_panel = NcfRelationErrorsPageViewPanel(driver)

    def get_ncf_relation_errors(self, timeout):
        return self._view_panel.get_ncf_relation_errors(timeout)

    def get_ncf_global_validation_errors(self, timeout):
        return self._view_panel.get_ncf_global_validation_errors(timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class NcfRelationErrorsPageViewPanel(RelationErrorsPageViewPanel):
    _ERROR_TABLE_ROWS_XPATH = '//ncf-parameter-validation-errors//tbody/tr'
    _GLOBAL_VALIDATION_ERRORS = '//global-validation-errors//tbody//span'

    def __init__(self, driver):
        super(NcfRelationErrorsPageViewPanel, self).__init__(driver)

    def get_ncf_relation_errors(self, timeout):
        return self.get_relation_errors(timeout)

    def get_ncf_global_validation_errors(self, timeout):
        try:
            self.wait_for_visibility_by_xpath(self._GLOBAL_VALIDATION_ERRORS, timeout)
            return [elem.text.strip() for elem in self.driver.find_elements_by_xpath(self._GLOBAL_VALIDATION_ERRORS)]
        except TimeoutException:
            logging.warning('can not find global validation errors module, pls check if there is this module on page.')
            return []
